import React, { useState } from 'react';
import { Menubar } from 'primereact/menubar';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="menubar-accessibility">Accessible Menubar</label>
            <Menubar 
                id="menubar-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible Menubar input"
                placeholder="Enter menubar"
            />
        </div>
    );
}